Q: java.lang.ClassCastException: com.sun.media.sound.DirectAudioDevice$DirectClip cannot be cast to javax.sound.sampled.SourceDataLine A: <p>You need to replace this:</p>
<pre><code>SourceDataLine.Info dli = new DataLine.Info(Clip.class, ais.getFormat());
SourceDataLine sdl = (SourceDataLine)AudioSystem.getLine(dli);
</code></pre>
<p>With:</p>
<pre><code>SourceDataLine.Info dli = new DataLine.Info(SourceDataLine.class, ais.getFormat());
SourceDataLine sdl = (SourceDataLine)AudioSystem.getLine(dli);
</code></pre>

Q: Multiple sheet(isPresented:) doesn&#39;t work in SwiftUI A: <p>If you want the sheet to be presented in a priority-aware order, the other answer</p>
<pre><code>.background(EmptyView()
        .sheet(isPresented: isPresented, content: content))
</code></pre>
<p>may present the sheet in an undefined order.</p>
<p>Check out this lightweight library <a href="https://github.com/DJBen/SwiftUIMultiSheet" rel="nofollow noreferrer">https://github.com/DJBen/SwiftUIMultiSheet</a> that preserves the user-defined priority order of the sheets</p>
<pre class="lang-swift prettyprint-override"><code>
import SwiftUIMultiSheet

@SheetRoute
enum AppSheet {
    case settings // Highest priority first 
    case paywall
    case detail(Int)
}

struct ContentView: View {
    @State private var router = MultiSheetRouter&lt;AppSheet&gt;()

    var body: some View {
        VStack {
            Toggle(&quot;Settings&quot;, isOn: router.bind(.settings))
            Toggle(&quot;Paywall&quot;, isOn: router.bind(.paywall))

            Button(&quot;Open Detail&quot;) {
                router.present(.detail(42))
            }
        }
        .multiSheet(router: router, onDismiss: { dismissedRoute, isFinal in
            // Optional: handle dismissal;
            // - isFinal is true: dismissal is due to removal of the route; sheet will never appear again
            // - isFinal is false: dismissal is due to a higher-priority sheet presenting over it
        }) { route in
            switch route {
            case .settings: SettingsView()
            case .paywall: PaywallView()
            case .detail(let id): Text(&quot;Detail \(id)&quot;)
            }
        }
    }
}
</code></pre>
